  },
  {
    "number": 9,
    "name": "what you believe",
    "job": "Beliefs and assumptions about how life works. Develop the card's general belief pattern, widen it into alternatives she can test, and let her recognize the fit; do not claim a hidden belief, habitual response, or private thought as established biography.",
    "blurb": "what you take to be true about how life works"
  },
  {
    "number": 10,
    "name": "your standing",
    "job": "Standing, reputation, position, and credit. Explain what the card says would make standing visible and how she can recognize the evidence; do not invent another person's private opinion or assert an unobserved workplace history.",
    "blurb": "how you are seen, and by the people whose opinion counts"
  },
  {
    "number": 11,
    "name": "your circle",
    "job": "Her circle and the observable ways people participate, arrive, connect, or go quiet. Explain the card's social pattern without assigning motives, trustworthiness, or a hidden reason to a particular person.",
    "blurb": "your friends, and who actually turns up"
  },
  {
    "number": 12,
    "name": "what is being kept from you",
    "job": "The blind room. What is real, close, and not visible from where she stands. ⭐ The house the letter promised the most and the one she will read first.",
    "blurb": "what is real and close, and not visible from where you are standing"
  }
];
const CARDS      = {
