const POOL       = ["death", "judgement", "justice", "strength", "temperance", "the-chariot", "the-devil", "the-empress", "the-fool", "the-hanged-man", "the-hermit", "the-hierophant", "the-high-priestess", "the-magician", "the-sun", "wheel-of-fortune"];         // every Major neither letter has spent
const ARCS        = {
